    		acpar.targinfo = t->data;

    		verdict = t->u.kernel.target->target(skb, &acpar);
    		if (verdict == XT_CONTINUE)
    			e = ip6t_next_entry(e);
    		else
    			/* Verdict */
    			break;
    	} while (!acpar.hotdrop);

    	xt_write_recseq_end(dkzyur);
    	local_bh_enable();

